package org.apache.parquet.crypto;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.lang.reflect.Field;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.parquet.crypto.AADPrefixVerifier;
import org.apache.parquet.crypto.DecryptionKeyRetriever;
import org.apache.parquet.crypto.FileDecryptionProperties;
import org.apache.parquet.crypto.KeyAccessDeniedException;
import org.apache.parquet.crypto.ParquetCipher;
import org.apache.parquet.crypto.ParquetCryptoRuntimeException;
import org.apache.parquet.format.EncryptionAlgorithm;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

public class InternalFileDecryptorSetFileCryptoMetaDataTests {

  @Test
  void initializesFileAadForAlgorithmWithoutPrefix() throws Exception {
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    EncryptionAlgorithm algorithm = aesGcm(fileUnique, false, null);

    InternalFileDecryptor decryptor = decryptorWithFooterKey();
    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(fileUnique, (byte[]) privateField(decryptor, "fileAAD"));
    assertSame(algorithm, privateField(decryptor, "algorithm"));
    assertEquals(false, privateField(decryptor, "encryptedFooter"));
  }

  @Test
  void combinesStoredAadPrefixWithFileUniqueComponent() throws Exception {
    byte[] prefix = new byte[] {9, 10, 11};
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    EncryptionAlgorithm algorithm = aesGcm(fileUnique, false, prefix);

    InternalFileDecryptor decryptor = decryptorWithAadPrefix(prefix);
    decryptor.setFileCryptoMetaData(algorithm, false, null);

    byte[] expected = new byte[prefix.length + fileUnique.length];
    System.arraycopy(prefix, 0, expected, 0, prefix.length);
    System.arraycopy(fileUnique, 0, expected, prefix.length, fileUnique.length);
    assertArrayEquals(expected, (byte[]) privateField(decryptor, "fileAAD"));
  }

  @Test
  void supportsAesGcmCtrAndRetrievesRequiredFooterKey() throws Exception {
    byte[] fileUnique = new byte[] {8, 7, 6, 5, 4, 3, 2, 1};
    byte[] metadata = new byte[] {42, 43};
    byte[] expectedKey = new byte[16];
    AtomicReference<byte[]> receivedMetadata = new AtomicReference<>();

    DecryptionKeyRetriever retriever = keyMetadata -> {
      receivedMetadata.set(keyMetadata);
      return expectedKey;
    };
    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withKeyRetriever(retriever)
        .withoutFooterSignatureVerification()
        .build();
    InternalFileDecryptor decryptor = new InternalFileDecryptor(properties);

    EncryptionAlgorithm algorithm = ParquetCipher.AES_GCM_CTR_V1.getEncryptionAlgorithm();
    algorithm.getAES_GCM_CTR_V1().setAad_file_unique(fileUnique);
    algorithm.getAES_GCM_CTR_V1().setSupply_aad_prefix(false);

    decryptor.setFileCryptoMetaData(algorithm, true, metadata);

    assertArrayEquals(metadata, receivedMetadata.get());
    assertNotNull(decryptor.fetchFooterDecryptor());
    assertArrayEquals(fileUnique, (byte[]) privateField(decryptor, "fileAAD"));
  }

  @Test
  void rejectsMissingRequiredAadPrefix() {
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    EncryptionAlgorithm algorithm = aesGcm(fileUnique, true, null);

    InternalFileDecryptor decryptor = decryptorWithFooterKey();

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  @Test
  void rejectsDifferentAadPrefix() {
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    byte[] filePrefix = new byte[] {1, 2, 3};
    byte[] propertyPrefix = new byte[] {4, 5, 6};
    EncryptionAlgorithm algorithm = aesGcm(fileUnique, false, filePrefix);

    InternalFileDecryptor decryptor = decryptorWithAadPrefix(propertyPrefix);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  @Test
  void rejectsPropertyPrefixWhenFileDoesNotUseOne() {
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    EncryptionAlgorithm algorithm = aesGcm(fileUnique, false, null);

    InternalFileDecryptor decryptor = decryptorWithAadPrefix(new byte[] {1, 2, 3});

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  @Test
  void invokesAndAcceptsAadPrefixVerifierForStoredPrefix() throws Exception {
    byte[] prefix = new byte[] {7, 8, 9};
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    AtomicReference<byte[]> verified = new AtomicReference<>();

    AADPrefixVerifier verifier = verified::set;
    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withFooterKey(new byte[16])
        .withAADPrefixVerifier(verifier)
        .build();
    InternalFileDecryptor decryptor = new InternalFileDecryptor(properties);
    EncryptionAlgorithm algorithm = aesGcm(fileUnique, false, prefix);

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(prefix, verified.get());
  }

  @Test
  void rejectsReuseWithDifferentFooterMetadata() {
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    byte[] originalMetadata = new byte[] {1, 2};
    EncryptionAlgorithm algorithm = aesGcm(fileUnique, false, null);
    InternalFileDecryptor decryptor = decryptorWithFooterKey();

    decryptor.setFileCryptoMetaData(algorithm, false, originalMetadata);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, new byte[] {3, 4}));
  }

  @Test
  void acceptsReuseWithEquivalentMetadataAndLeavesFileAadUnchanged() throws Exception {
    byte[] fileUnique = new byte[] {1, 2, 3, 4, 5, 6, 7, 8};
    byte[] metadata = new byte[] {1, 2};
    EncryptionAlgorithm first = aesGcm(fileUnique, false, null);
    EncryptionAlgorithm equivalent = aesGcm(fileUnique, false, null);
    InternalFileDecryptor decryptor = decryptorWithFooterKey();

    decryptor.setFileCryptoMetaData(first, false, metadata);
    byte[] before = ((byte[]) privateField(decryptor, "fileAAD")).clone();

    decryptor.setFileCryptoMetaData(equivalent, false, metadata);

    assertArrayEquals(before, (byte[]) privateField(decryptor, "fileAAD"));
  }

  @Test
  void wrapsKeyAccessDeniedExceptionWithFooterContext() {
    byte[] metadata = new byte[] {9, 9};
    KeyAccessDeniedException cause = new KeyAccessDeniedException("denied");
    DecryptionKeyRetriever retriever = ignored -> {
      throw cause;
    };
    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withKeyRetriever(retriever)
        .withoutFooterSignatureVerification()
        .build();
    InternalFileDecryptor decryptor = new InternalFileDecryptor(properties);
    EncryptionAlgorithm algorithm = aesGcm(
        new byte[] {1, 2, 3, 4, 5, 6, 7, 8}, false, null);

    KeyAccessDeniedException thrown = assertThrows(
        KeyAccessDeniedException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, true, metadata));

    assertEquals("Footer key: access denied", thrown.getMessage());
    assertSame(cause, thrown.getCause());
  }

  private static EncryptionAlgorithm aesGcm(
      byte[] fileUnique, boolean supplyPrefix, byte[] storedPrefix) {
    EncryptionAlgorithm algorithm = ParquetCipher.AES_GCM_V1.getEncryptionAlgorithm();
    algorithm.getAES_GCM_V1().setAad_file_unique(fileUnique);
    algorithm.getAES_GCM_V1().setSupply_aad_prefix(supplyPrefix);
    if (storedPrefix != null) {
      algorithm.getAES_GCM_V1().setAad_prefix(storedPrefix);
    }
    return algorithm;
  }

  private static InternalFileDecryptor decryptorWithFooterKey() {
    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withFooterKey(new byte[16])
        .build();
    return new InternalFileDecryptor(properties);
  }

  private static InternalFileDecryptor decryptorWithAadPrefix(byte[] prefix) {
    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withFooterKey(new byte[16])
        .withAADPrefix(prefix)
        .withoutFooterSignatureVerification()
        .build();
    return new InternalFileDecryptor(properties);
  }

  private static Object privateField(InternalFileDecryptor decryptor, String name)
      throws ReflectiveOperationException {
    Field field = InternalFileDecryptor.class.getDeclaredField(name);
    field.setAccessible(true);
    return field.get(decryptor);
  }
}
